import html
import json
from pathlib import Path


def render(report,directory):
    esc=lambda s:html.escape(str(s))
    cases=report.get('http_summary',[])
    primary=cases[0] if cases else None
    baseline=primary['policies']['configured_baseline'] if primary else {}
    candidate=primary['policies']['ai_patch'] if primary else {}
    improvement=primary['improvement'] if primary else {}
    req_before=f"{baseline['requests']:g}" if 'requests' in baseline else '—'
    req_after=f"{candidate['requests']:g}" if 'requests' in candidate else '—'
    time_before=f"{baseline['completion_seconds']:.2f}s" if 'completion_seconds' in baseline else '—'
    time_after=f"{candidate['completion_seconds']:.2f}s" if 'completion_seconds' in candidate else '—'
    req_gain=f"{improvement['request_reduction']*100:.0f}%" if improvement else '—'
    time_gain=f"{improvement['completion_reduction']*100:.0f}%" if improvement else '—'
    jobs=primary['scenario']['jobs'] if primary else 48
    digest=candidate.get('output_sha256') or 'Available after HTTP confirmation'
    validation=report.get('validation_summary',{}).get('ai_patch',{})
    passed=f"{validation['correct']}/{validation['cases']}" if validation else 'Measuring'
    run_label=('Live AI optimization, HTTP-confirmed' if report['status']=='verified_demo' else 'Live AI experiment') if report['agent']=='codex' else 'Fresh HTTP replay of a recorded AI patch' if report['agent']=='replay' else 'Configured baseline evaluation'
    verified=report['status']=='verified_demo'
    state='Verified over local HTTP' if verified else 'Experiment running' if report['status']=='running' else 'Verification requires review'
    source=directory/'selected.py'
    selected_trial=next((t for t in report.get('trials',[]) if t.get('source')==report.get('selected_source')),None)
    proposal_href=f"proposal-{selected_trial['iteration']}.json" if selected_trial else 'report.json'
    diff_path=directory/(Path(report.get('selected_source','baseline.py')).stem+'.diff')
    diff=diff_path.read_text() if diff_path.exists() else 'The source patch will appear after model selection.'
    diff_html='\n'.join('<span class="'+('add' if line.startswith('+') else 'remove' if line.startswith('-') else '')+'">'+esc(line)+'</span>' for line in diff.splitlines())
    rows=[]
    for case in cases:
        b,a=case['policies']['configured_baseline'],case['policies']['ai_patch']
        gain=case['improvement']
        rows.append(f'<tr><td>{esc(case["scenario"]["name"])}</td><td>{b.get("requests","—")} → <b>{a.get("requests","—")}</b></td><td>{b.get("completion_seconds",0):.3f}s → <b>{a.get("completion_seconds",0):.3f}s</b></td><td>{gain.get("request_reduction",0)*100:.1f}%</td><td>{"Identical" if a.get("output_sha256")==b.get("output_sha256") and a.get("output_sha256") else "Pending"}</td></tr>')
    baseline_ops=baseline.get('requests_by_operation',{});candidate_ops=candidate.get('requests_by_operation',{})
    op_rows=''.join(f'<div class="op"><span>{name}</span><span>{baseline_ops.get(key,"—")} <em>→</em> <b>{candidate_ops.get(key,"—")}</b></span></div>' for key,name in [('category','Category lookups'),('fx','Exchange-rate lookups'),('inventory','Per-item inventory'),('write','Product writes')])
    optimality_path=directory/'optimality.json'
    optimality=json.loads(optimality_path.read_text())['http_cases'][0] if optimality_path.exists() else None
    proof_html=''
    if optimality and primary:
        bound=optimality['minimum_total_requests']
        cat=sum(g['minimum_requests'] for g in optimality['lookup_scopes'] if g['kind']=='category')
        fx=sum(g['minimum_requests'] for g in optimality['lookup_scopes'] if g['kind']=='fx')
        hit=candidate.get('requests')==bound
        proof_html=f'<section class="section card"><div class="eyebrow">Request-count optimality under the declared API</div><h2>{bound} requests is the minimum. {"The AI patch reaches it." if hit else "Compare the patch with this bound."}</h2><p>Every product requires one item-bound inventory read and one write: {jobs} + {jobs} requests. The required category and FX receipts need at least {cat} + {fx} scoped bulk lookups. Total: <b class="green">{jobs} + {jobs} + {cat} + {fx} = {bound}</b>.</p><p class="caption">Cold-start workload; snapshots are immutable within tenant scope; bulk lookup is limited to {primary["scenario"]["batch_size"]} keys in one scope. This proves a request-count lower bound for the declared contract, not latency optimality or production performance. <a href="optimality.json">Inspect the derivation →</a></p></section>'
    manual=primary['policies'].get('manual_semantic_reference',{}) if primary else {}
    manual_text=(f"{manual.get('requests','—')} requests · {manual.get('completion_seconds',0):.3f}s") if manual else 'Pending'
    rationale=selected_trial.get('rationale','The agent reads the original integration and measured traces, then proposes a source patch.') if selected_trial else 'The agent reads the original integration and measured traces, then proposes a source patch.'
    gate_rows=''.join(f'<div class="check"><span class="{ "green" if value else "amber" }">{ "✓" if value else "·" }</span>{esc(key.replace("_"," "))}</div>' for key,value in report.get('gates',{}).items())
    text='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Tempo · Do less work. Ship the same result.</title><style>
:root{color-scheme:dark;--bg:#080d16;--surface:#101a29;--line:#25364c;--muted:#9cacc1;--mint:#8ef0cc;--blue:#a3baff}*{box-sizing:border-box}body{margin:0;background:radial-gradient(ellipse at 80% 0%,#132d36 0,transparent 45%),var(--bg);color:#eef4ff;font:14px/1.65 -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}main{max-width:1180px;margin:auto;padding:0 30px 70px}nav{display:flex;justify-content:space-between;align-items:center;height:88px;border-bottom:1px solid var(--line)}.logo{font-size:29px;letter-spacing:-1.5px;font-weight:850}.logo b{color:var(--mint)}.nav-right{display:flex;gap:18px;align-items:center}.pill{font-size:11px;border:1px solid #35574f;color:var(--mint);border-radius:30px;padding:7px 13px}a{color:var(--mint);text-decoration:none}.subtle{color:var(--muted);font-size:12px}.eyebrow{font-size:10px;letter-spacing:2.3px;font-weight:750;color:var(--mint);text-transform:uppercase}.hero{padding:65px 0 40px;display:grid;grid-template-columns:1.35fr .9fr;gap:60px;align-items:center}h1{font-size:clamp(38px,5.2vw,66px);line-height:1.04;letter-spacing:-3px;margin:17px 0 22px;font-weight:750}h1 span{color:var(--mint)}p{color:var(--muted);max-width:700px}.lead{font-size:16px;line-height:1.75;max-width:610px}.actions{display:flex;gap:12px;margin-top:25px;align-items:center;flex-wrap:wrap}button,.button{font:inherit;border:0;background:var(--mint);color:#08231b;padding:12px 18px;border-radius:8px;font-weight:750;cursor:pointer;display:inline-block}.secondary{background:transparent;color:#e2ecfb;border:1px solid var(--line)}button:disabled{opacity:.5;cursor:wait}.hero-proof{background:linear-gradient(145deg,#162b34,#111c2b);border:1px solid #315047;border-radius:18px;padding:26px}.hero-proof .big{font-size:70px;letter-spacing:-4px;font-weight:750;color:var(--mint);line-height:1.15;margin:14px 0 4px}.tiny{font-size:11px;color:var(--muted)}.proof-line{border-top:1px solid #2a4446;margin-top:20px;padding-top:16px;display:flex;justify-content:space-between}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}.metric{background:#101a29;border:1px solid var(--line);border-radius:12px;padding:20px}.metric b{display:block;font-size:29px;letter-spacing:-1px}.metric span{color:var(--muted);font-size:11px}.section{margin-top:38px}h2{font-size:25px;letter-spacing:-.7px;line-height:1.2;margin:8px 0 14px}.two{display:grid;grid-template-columns:1fr 1fr;gap:20px}.card{background:var(--surface);border:1px solid var(--line);border-radius:14px;padding:25px}.card.optimized{border-color:#426c60;background:linear-gradient(160deg,#132c2b,#111c2b)}.label{font-size:10px;letter-spacing:1.5px;text-transform:uppercase;color:var(--muted)}.value{font-size:36px;font-weight:750;letter-spacing:-1.3px;margin:12px 0}.value small{font-size:13px;color:var(--muted);font-weight:400;letter-spacing:0}.flow{display:flex;gap:7px;align-items:center;margin:20px 0;flex-wrap:wrap}.flow span{padding:7px 9px;border:1px solid #344b62;background:#0d1622;border-radius:5px;font-size:11px}.flow i{color:var(--muted);font-style:normal}.op{display:flex;justify-content:space-between;padding:10px 0;border-bottom:1px solid var(--line)}.op em{color:var(--muted);font-style:normal;padding:0 12px}.op b{color:var(--mint)}.op:last-child{border:0}.green{color:var(--mint)}.amber{color:#ffc793}.checks{display:grid;grid-template-columns:1fr 1fr;gap:10px}.check{font-size:12px;color:#c8d7eb}.check span{padding-right:10px}.hash{font:12px/1.8 ui-monospace,SFMono-Regular,monospace;overflow-wrap:anywhere;background:#0a1420;border:1px solid #294b45;border-radius:8px;padding:14px;color:#b6f7dc}.scroll{overflow:auto}table{width:100%;border-collapse:collapse;text-align:left;font-size:12px}td,th{padding:13px 10px;border-bottom:1px solid var(--line);white-space:nowrap}th{color:var(--muted);font-size:10px;text-transform:uppercase;letter-spacing:.8px}td b{color:var(--mint)}pre{background:#080f19;border:1px solid var(--line);border-radius:10px;padding:22px;font:11px/1.7 ui-monospace,SFMono-Regular,monospace;overflow:auto;max-height:600px}pre .add{color:#8af0c7}pre .remove{color:#ec9292}summary{cursor:pointer;font-weight:650;padding:13px 0}.caption{font-size:11px;color:var(--muted);margin-top:12px}.divider{border-top:1px solid var(--line);margin-top:35px;padding-top:25px}footer{margin-top:45px;color:var(--muted);font-size:11px}.live-log{white-space:pre-wrap;font:11px/1.8 monospace;color:#bfd4eb;margin-top:16px;max-height:200px;overflow:auto}#run-note{margin-top:10px;min-height:18px}.step{color:var(--mint);font-size:10px;letter-spacing:1px}.controls{display:flex;gap:12px;align-items:center;flex-wrap:wrap}select{background:#0b1522;color:#d9e7fa;border:1px solid var(--line);border-radius:8px;padding:11px;font:inherit}@media(max-width:800px){.hero{grid-template-columns:1fr;gap:20px;padding-top:35px}.metrics{grid-template-columns:1fr 1fr}.two{grid-template-columns:1fr}h1{letter-spacing:-2px}.nav-right .subtle{display:none}.checks{grid-template-columns:1fr}main{padding:0 20px 45px}}
</style></head><body><main>'''
    text+=f'''<nav><div class="logo">tempo<b>.</b></div><div class="nav-right"><a class="subtle" href="/lab">Engineering lab</a><span class="pill">{esc(state)}</span></div></nav>
<section class="hero"><div><div class="eyebrow">AI optimization for API integrations</div><h1>Do less work.<br><span>Ship the same result.</span></h1><p class="lead">Tempo finds repeated API work in a catalog integration, proposes a source patch, and verifies that every enriched product stays identical.</p><div class="actions"><a class="button" href="#patch">Inspect the AI patch ↓</a><button class="secondary" id="rerun">Re-run HTTP benchmark</button></div><div id="run-note" class="tiny">{esc(run_label)} · {jobs} products · three enrichment reads and one write per product before optimization</div></div><div class="hero-proof"><div class="eyebrow">Measured request reduction</div><div class="big">{req_gain}</div><p>fewer HTTP requests for the same catalog output</p><div class="proof-line"><span>{req_before} → <b class="green">{req_after}</b> requests</span><span>{time_gain} less completion time</span></div><div class="tiny" style="margin-top:14px">Median across three local HTTP repetitions. Authored synthetic API contract.</div></div></section>
<div class="metrics"><div class="metric"><b>{jobs}</b><span>products preserved in the demo</span></div><div class="metric"><b>{passed}</b><span>validation scenarios correct</span></div><div class="metric"><b>{candidate.get('duplicate_side_effects','—')}</b><span>duplicate write effects</span></div><div class="metric"><b>{'Identical' if verified else 'Checking'}</b><span>complete output SHA-256</span></div></div>
<section class="section"><div class="eyebrow">The source-level improvement</div><h2>A configured client. A smarter workflow.</h2><div class="two"><div class="card"><div class="label">Before · robust retries and rate limiting</div><div class="value">{time_before} <small>HTTP completion</small></div><div class="flow"><span>Category lookup</span><i>→</i><span>FX lookup</span><i>→</i><span>Inventory</span><i>→</i><span>Write</span></div><p>Each product repeats category and exchange-rate calls. Rate limiting schedules this work correctly, but every repeated lookup still consumes a request.</p></div><div class="card optimized"><div class="label green">After · AI-generated dataflow patch</div><div class="value">{time_after} <small>HTTP completion</small></div><div class="flow"><span>Shared snapshot lookups</span><i>→</i><span>Per-item inventory</span><i>→</i><span>Write</span></div><p>Batch and share immutable lookups by tenant and snapshot. Keep each inventory read and each product write. The transport and retry helpers stay identical.</p></div></div></section>
<section class="section two"><div class="card"><div class="eyebrow">Measured operations</div><h2>Where the requests went</h2>{op_rows}<p class="caption">Counts include retries. Bulk lookups cost one request under the declared controlled API contract.</p></div><div class="card"><div class="eyebrow">Executable verification</div><h2>Every output, checked</h2><p>The server validates tenant/snapshot-scoped read receipts, the transformed price, item-specific inventory, and idempotent writes. The complete output vectors match.</p><div class="hash">{esc(digest)}</div><p class="caption">The original and patched integrations produce the same SHA-256 for the full demo output.</p></div></section>
<section class="section card"><div class="eyebrow">Repeated HTTP confirmation</div><h2>Three declared catalog workloads</h2><div class="scroll"><table><tr><th>Workload</th><th>Requests before → after</th><th>Median completion before → after</th><th>Request reduction</th><th>Outputs</th></tr>{''.join(rows)}</table></div><p class="caption">Each workload runs with fresh server state. No warm cache crosses runs. Execution order rotates between repetitions.</p></section>
{proof_html}<section id="patch" class="section card"><div class="eyebrow">Real model output</div><h2>The reviewable source patch</h2><p>{esc(rationale)}</p><details><summary>Open source diff</summary><pre>{diff_html}</pre></details><div class="controls"><button class="secondary" id="new-ai">Generate a new AI patch</button><a class="button secondary" href="selected.py">Selected Python source</a><a class="button secondary" href="{esc(proposal_href)}">Model response</a><a class="button secondary" href="report.json">Raw experiment evidence</a><a class="button secondary" href="scenarios.json">Declared scenarios</a></div></section>
<section class="section card"><div class="eyebrow">Verification receipt</div><h2>Acceptance checks</h2><div class="checks">{gate_rows or '<p>Measurements are running; no final verdict has been issued.</p>'}</div><details class="divider"><summary>Comparators, scope and audit trail</summary><p>The configured baseline already uses burst-aware quota admission, concurrency limits, stable write keys, bounded retries and timeouts. Only business dataflow is changed. A manually authored semantic reference produced {esc(manual_text)}. Matching that implementation shows that the AI applied ordinary batching and sharing correctly; no novel algorithm or superiority over expert redesign is claimed.</p><p>Lookups are explicitly immutable within (tenant, snapshot). A batch costs one request. The inventory proof remains item-specific. These are synthetic provider assumptions, not claims about a named production API.</p><p>The validation matrix includes tenant/snapshot collisions, batch size one, and a low-sharing boundary. Correctness is required there; a speedup is not promised for every workload. All proposal attempts and earlier experiments remain available in the engineering lab.</p><p>Source SHA-256: <code>{esc(report.get('selected_sha256','pending'))}</code></p></details></section>
<footer>Tempo · Source-level integration optimization · Real Python coroutines and local HTTP · Synthetic workload, not a production benchmark · Driver: {esc(report['agent'])}</footer>'''
    text+='''<script>
let active=false;
const note=document.getElementById('run-note'),button=document.getElementById('rerun');
async function launch(driver){if(active)return;active=true;button.disabled=true;document.getElementById('new-ai').disabled=true;note.textContent=driver==='codex'?'Starting a new live Codex optimization and HTTP verification. Uses configured Codex usage.':'Starting a fresh HTTP replay of the recorded AI patch. No model call is made.';try{const r=await fetch('/api/run',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({example:'catalog_showcase',driver:driver})});const d=await r.json();if(!r.ok)throw new Error(d.error||'Launch failed');const timer=setInterval(async()=>{try{const state=await(await fetch('/api/status')).json();note.textContent=state.running?'Experiment is running. Fresh measurements will appear when it completes.':'Benchmark complete. Loading the new evidence…';if(!state.running){clearInterval(timer);location.href='/'}}catch(e){clearInterval(timer);note.textContent=e.message;active=false;button.disabled=false}},2000)}catch(e){note.textContent='CLI alternative: python3 tempo_prototype/tempo_catalog.py --agent replay --proposal tempo_prototype/catalog/saved-proposal.json. '+e.message;active=false;button.disabled=false;document.getElementById('new-ai').disabled=false}}
button.onclick=()=>launch('replay');document.getElementById('new-ai').onclick=()=>launch('codex');
</script></main></body></html>'''
    (directory/'index.html').write_text(text)
